package com.coffeeshop.controller;import com.coffeeshop.model.NotificationModels.Notification;import com.coffeeshop.security.ApplicationSession;import com.coffeeshop.service.NotificationService;import javafx.application.Platform;import javafx.beans.property.SimpleStringProperty;import javafx.fxml.FXML;import javafx.scene.control.*;import java.util.*;import java.util.concurrent.CompletableFuture;public final class NotificationsController{private final NotificationService service;private final ApplicationSession session;@FXML private ChoiceBox<String>readFilter;@FXML private TableView<Notification>notificationTable;@FXML private TableColumn<Notification,String>typeColumn,titleColumn,messageColumn,createdColumn,statusColumn;@FXML private Label messageLabel;@FXML private Button readButton,generateButton;public NotificationsController(NotificationService s,ApplicationSession a){service=Objects.requireNonNull(s);session=Objects.requireNonNull(a);}@FXML private void initialize(){typeColumn.setCellValueFactory(v->text(v.getValue().type().replace('_',' ')));titleColumn.setCellValueFactory(v->text(v.getValue().title()));messageColumn.setCellValueFactory(v->text(v.getValue().message()));createdColumn.setCellValueFactory(v->text(v.getValue().createdAt().toString().replace('T',' ')));statusColumn.setCellValueFactory(v->text(v.getValue().read()?"Read":"Unread"));readFilter.getItems().setAll("Unread","Read","All");readFilter.setValue("Unread");readFilter.valueProperty().addListener((o,a,b)->refresh());notificationTable.getSelectionModel().selectedItemProperty().addListener((o,a,b)->readButton.setDisable(b==null||b.read()));var u=session.currentUser().orElseThrow();generateButton.setDisable(!u.hasRole("ADMIN")&&!u.hasRole("MANAGER"));refresh();}@FXML private void refresh(){Boolean read="All".equals(readFilter.getValue())?null:"Read".equals(readFilter.getValue());CompletableFuture.supplyAsync(()->service.notifications(user(),read)).whenComplete((v,e)->Platform.runLater(()->{if(e!=null){messageLabel.setText("Unable to load notifications.");return;}notificationTable.getItems().setAll(v);messageLabel.setText(v.isEmpty()?"No notifications match the filter.":"");readButton.setDisable(true);}));}@FXML private void markRead(){Notification n=notificationTable.getSelectionModel().getSelectedItem();if(n!=null)write(()->service.markRead(n,user()),"Notification marked read.");}@FXML private void generate(){var u=session.currentUser().orElseThrow();CompletableFuture.supplyAsync(()->service.generateLowStock(u.hasRole("ADMIN")||u.hasRole("MANAGER"))).whenComplete((n,e)->Platform.runLater(()->{if(e==null){refresh();messageLabel.setText(n+" new low-stock alert(s) generated.");}else messageLabel.setText(message(e));}));}private void write(Runnable r,String ok){CompletableFuture.runAsync(r).whenComplete((v,e)->Platform.runLater(()->{if(e==null){refresh();messageLabel.setText(ok);}else messageLabel.setText(message(e));}));}private long user(){return session.currentUser().orElseThrow().userId();}private static SimpleStringProperty text(String s){return new SimpleStringProperty(s);}private static String message(Throwable e){Throwable x=e;while(x.getCause()!=null)x=x.getCause();return x instanceof IllegalArgumentException||x instanceof IllegalStateException||x instanceof SecurityException?x.getMessage():"Unable to update notifications.";}}
